actions.command:
mkdir -p /workspace/src && cat > /workspace/src/entr.c <<'EOF'
/*
 * entr - run arbitrary commands when files change
 *
 * Original implementation written from observed behaviour of the reference
 * executable.  Linux only: file system events are obtained through inotify.
 */
#define _GNU_SOURCE
#include <sys/types.h>
#include <sys/inotify.h>
#include <sys/resource.h>
#include <sys/stat.h>
#include <sys/wait.h>

#include <dirent.h>
#include <err.h>
#include <errno.h>
#include <fcntl.h>
#include <libgen.h>
#include <limits.h>
#include <poll.h>
#include <pwd.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

#define RELEASE "5.7"

/* event flags, named after the kqueue vnode filter they emulate */
#define NOTE_DELETE 0x0001
#define NOTE_WRITE  0x0002
#define NOTE_EXTEND 0x0004
#define NOTE_ATTRIB 0x0008
#define NOTE_RENAME 0x0020

#define MAX_EVENTS     32      /* events processed per wake up */
#define SETTLE_MS      50      /* quiet period used to batch events */
#define REOPEN_TRIES   20      /* attempts to locate a replaced file */
#define DIR_SETTLE_N   10      /* directory settle polls (50ms each) */

typedef struct watch_file {
	char *fn;
	int wd;
	mode_t mode;
	int is_dir;
	int dir_count;
} WatchFile;

typedef struct {
	WatchFile *file;
	unsigned int fflags;
} Event;

/* options */
static int aggressive_opt;
static int clear_opt;
static int dirwatch_opt;
static int noninteractive_opt;
static int postpone_opt;
static int restart_opt;
static int shell_opt;
static int status_opt;
static int oneshot_opt;

/* environment driven behaviour */
static int ev_trace;
static int follow_symlinks;
static int inotify_workaround;
static int restart_signal = SIGTERM;

/* state */
static WatchFile **files;
static int nfiles;
static int files_cap;
static int open_max;
static int ifd = -1;            /* inotify descriptor */
static int tty_fd = -1;
static struct termios tty_orig;
static int tty_saved;
static int sigpipe_fd[2] = { -1, -1 };
static pid_t child_pid = -1;    /* persistent child when -r is used */
static int child_status;
static pid_t status_pid = -1;   /* awk status filter */
static int status_wfd = -1;
static int status_terminated;
static WatchFile *leading_edge;
static int terminate_flag;

static volatile sig_atomic_t got_sigint;
static volatile sig_atomic_t got_sigterm;
static volatile sig_atomic_t got_sighup;
static volatile sig_atomic_t got_sigchld;

static const char *status_template =
    "# http://eradman.com/entrproject/status-filters.html\n"
    "/^signal/ { print $3, \"terminated by signal\", $2; }\n"
    "/^exit/ { print $3, \"returned exit code\", $2; }\n";

/* ------------------------------------------------------------------------ */

static void
usage(void)
{
	fprintf(stderr, "release: %s\n", RELEASE);
	fprintf(stderr, "usage: entr [-acdnprsxz] utility [argument [/_] ...] < filenames\n");
}

static void
summary(void)
{
	printf("summary:\n");
	printf("    -a  Do not consolidate events\n");
	printf("    -c  Clear screen before execution\n");
	printf("    -d  Track files added or removed from directories\n");
	printf("    -n  Non-interactive mode\n");
	printf("    -p  Wait for first event\n");
	printf("    -r  Run as a background process, use signal to restart\n");
	printf("    -s  Evaluate using a shell\n");
	printf("    -x  Format exit status\n");
	printf("    -z  Exit after the utility completes\n");
	printf("docs:\n");
	printf("    man entr\n");
}

static void
restore_tty(void)
{
	if (tty_saved && tty_fd != -1)
		tcsetattr(tty_fd, TCSANOW, &tty_orig);
}

static void
tty_raw(void)
{
	struct termios raw;

	if (!tty_saved)
		return;
	raw = tty_orig;
	raw.c_lflag &= ~(ICANON | ECHO);
	tcsetattr(tty_fd, TCSANOW, &raw);
}

static void
msleep(int ms)
{
	struct timespec ts;

	ts.tv_sec = ms / 1000;
	ts.tv_nsec = (long)(ms % 1000) * 1000000L;
	while (nanosleep(&ts, &ts) == -1 && errno == EINTR)
		;
}

static int
xstat(const char *fn, struct stat *sb)
{
	if (follow_symlinks)
		return stat(fn, sb);
	return lstat(fn, sb);
}

/* ------------------------------------------------------------------------ */
/* signals */

static void
sig_handler(int signum)
{
	char c = (char)signum;

	switch (signum) {
	case SIGINT:  got_sigint = 1; break;
	case SIGTERM: got_sigterm = 1; break;
	case SIGHUP:  got_sighup = 1; break;
	case SIGCHLD: got_sigchld = 1; break;
	}
	if (sigpipe_fd[1] != -1)
		(void)write(sigpipe_fd[1], &c, 1);
}

static void
install_signals(void)
{
	struct sigaction sa;

	if (pipe2(sigpipe_fd, O_CLOEXEC | O_NONBLOCK) == -1)
		err(1, "pipe");
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = sig_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	sigaction(SIGINT, &sa, NULL);
	sigaction(SIGTERM, &sa, NULL);
	sigaction(SIGHUP, &sa, NULL);
	sigaction(SIGCHLD, &sa, NULL);
}

static int
wait_status_code(int st)
{
	if (WIFEXITED(st))
		return WEXITSTATUS(st);
	if (WIFSIGNALED(st))
		return 128 + WTERMSIG(st);
	return 0;
}

static void
stop_child(void)
{
	int st;

	if (child_pid <= 0)
		return;
	killpg(child_pid, restart_signal);
	while (waitpid(child_pid, &st, 0) == -1) {
		if (errno != EINTR)
			break;
	}
	child_pid = -1;
}

/* exit entr; a persistent child is terminated first */
static void
terminate(int signum)
{
	stop_child();
	restore_tty();
	if (signum == SIGTERM) {
		signal(SIGTERM, SIG_DFL);
		raise(SIGTERM);
	}
	exit(0);
}

/* reap children that are not waited for elsewhere */
static void
reap_children(void)
{
	pid_t pid;
	int st;

	for (;;) {
		pid = waitpid(-1, &st, WNOHANG);
		if (pid <= 0)
			break;
		if (pid == status_pid) {
			warnx("status process terminated");
			status_pid = -1;
			status_terminated = 1;
		} else if (pid == child_pid) {
			child_pid = -1;
			child_status = wait_status_code(st);
			if (oneshot_opt) {
				restore_tty();
				exit(child_status);
			}
		}
	}
}

static void
check_signals(void)
{
	if (got_sigchld) {
		got_sigchld = 0;
		reap_children();
	}
	if (status_terminated)
		terminate(0);
	if (got_sigterm)
		terminate(SIGTERM);
	if (got_sigint || got_sighup)
		terminate(0);
}

/* ------------------------------------------------------------------------ */
/* restart signal */

static void
parse_restart_signal(void)
{
	static const struct {
		const char *name;
		int signum;
	} table[] = {
		{ "HUP", SIGHUP }, { "INT", SIGINT }, { "QUIT", SIGQUIT },
		{ "TERM", SIGTERM }, { "USR1", SIGUSR1 }, { "USR2", SIGUSR2 },
	};
	const char *name;
	size_t i, n;

	name = getenv("ENTR_RESTART_SIGNAL");
	if (name == NULL)
		return;
	if (strncmp(name, "SIG", 3) == 0)
		name += 3;
	/*
	 * Only the first three entries of the table are consulted; this
	 * matches the behaviour of the reference implementation.
	 */
	n = sizeof(table) / (sizeof(table[0]) * 2);
	for (i = 0; i < n; i++) {
		if (strcmp(name, table[i].name) == 0) {
			restart_signal = table[i].signum;
			return;
		}
	}
	errx(1, "unrecognized signal: %s <> (HUP, INT, QUIT, TERM, USR1, USR2)", name);
}

/* ------------------------------------------------------------------------ */
/* watch list */

static int
read_open_max(void)
{
	FILE *fp;
	int n = 0;
	struct rlimit rl;

	fp = fopen("/proc/sys/fs/inotify/max_user_watches", "r");
	if (fp != NULL) {
		if (fscanf(fp, "%d", &n) != 1)
			n = 0;
		fclose(fp);
	}
	if (n <= 0) {
		if (getrlimit(RLIMIT_NOFILE, &rl) == 0)
			n = (int)rl.rlim_cur;
		else
			n = 1024;
	}
	return n;
}

static int
count_dir_entries(const char *fn)
{
	DIR *d;
	struct dirent *de;
	int count = 0;

	d = opendir(fn);
	if (d == NULL)
		errx(1, "unable to open directory: '%s'", fn);
	while ((de = readdir(d)) != NULL) {
		if (dirwatch_opt < 2 && de->d_name[0] == '.')
			continue;
		count++;
	}
	closedir(d);
	return count;
}

/* returns 1 if the number of directory entries differs from the baseline */
static int
compare_dir_contents(WatchFile *file)
{
	return count_dir_entries(file->fn) != file->dir_count;
}

static uint32_t
watch_mask(void)
{
	uint32_t mask;

	mask = IN_CLOSE_WRITE | IN_ATTRIB | IN_DELETE_SELF | IN_MOVE_SELF |
	    IN_CREATE | IN_DELETE | IN_MOVED_FROM | IN_MOVED_TO;
	if (inotify_workaround)
		mask |= IN_MODIFY;
	if (!follow_symlinks)
		mask |= IN_DONT_FOLLOW;
	return mask;
}

static void
watch_file(WatchFile *file)
{
	int wd;

	wd = inotify_add_watch(ifd, file->fn, watch_mask());
	if (wd == -1)
		err(1, "failed to register VNODE event");
	file->wd = wd;
}

static WatchFile *
find_file(const char *fn)
{
	int i;

	for (i = 0; i < nfiles; i++)
		if (strcmp(files[i]->fn, fn) == 0)
			return files[i];
	return NULL;
}

static WatchFile *
add_file(const char *fn, mode_t mode)
{
	WatchFile *file;

	if (nfiles + 1 >= open_max)
		errx(1, "Too many files listed; the hard limit for your login "
		    "class is %d. Please consult "
		    "http://eradman.com/entrproject/limits.html", open_max);
	if (nfiles == files_cap) {
		files_cap = files_cap ? files_cap * 2 : 64;
		files = realloc(files, sizeof(*files) * files_cap);
		if (files == NULL)
			err(1, "realloc");
	}
	file = calloc(1, sizeof(*file));
	if (file == NULL)
		err(1, "calloc");
	file->fn = strdup(fn);
	if (file->fn == NULL)
		err(1, "strdup");
	file->mode = mode;
	file->is_dir = S_ISDIR(mode);
	file->wd = -1;
	files[nfiles++] = file;
	return file;
}

static void
add_parent_dir(const char *fn)
{
	char *copy, *dir;
	struct stat sb;

	copy = strdup(fn);
	if (copy == NULL)
		err(1, "strdup");
	dir = dirname(copy);
	if (find_file(dir) == NULL && stat(dir, &sb) == 0 && S_ISDIR(sb.st_mode))
		add_file(dir, sb.st_mode);
	free(copy);
}

static void
read_file_list(FILE *fp)
{
	char buf[PATH_MAX + 2];
	struct stat sb;
	size_t len;
	int i, n;

	while (fgets(buf, sizeof(buf), fp) != NULL) {
		len = strlen(buf);
		while (len > 0 && buf[len - 1] == '\n')
			buf[--len] = '\0';
		if (len == 0)
			continue;
		if (xstat(buf, &sb) == -1) {
			warnx("unable to stat '%s'", buf);
			continue;
		}
		if (!S_ISREG(sb.st_mode) && !S_ISDIR(sb.st_mode) &&
		    !S_ISLNK(sb.st_mode))
			continue;
		add_file(buf, sb.st_mode);
	}
	if (dirwatch_opt > 0) {
		n = nfiles;
		for (i = 0; i < n; i++)
			if (!files[i]->is_dir)
				add_parent_dir(files[i]->fn);
	}
}

/* ------------------------------------------------------------------------ */
/* event collection */

static unsigned int
mask_to_fflags(uint32_t mask)
{
	unsigned int ff = 0;

	if (mask & IN_ATTRIB)
		ff |= NOTE_ATTRIB;
	if (mask & (IN_CLOSE_WRITE | IN_MODIFY))
		ff |= NOTE_WRITE;
	if (mask & (IN_CREATE | IN_DELETE))
		ff |= NOTE_WRITE;
	if (mask & IN_DELETE_SELF)
		ff |= NOTE_DELETE;
	if (mask & (IN_MOVE_SELF | IN_MOVED_FROM | IN_MOVED_TO))
		ff |= NOTE_RENAME;
	return ff;
}

static WatchFile *
file_by_wd(int wd)
{
	int i;

	for (i = 0; i < nfiles; i++)
		if (files[i]->wd == wd)
			return files[i];
	return NULL;
}

/* read everything queued on the inotify descriptor into the event list */
static void
collect_inotify(Event *list, int *count, int max)
{
	char buf[64 * 1024] __attribute__((aligned(8)));
	ssize_t n;
	size_t off;
	struct inotify_event *ie;
	WatchFile *file;
	unsigned int ff;

	for (;;) {
		n = read(ifd, buf, sizeof(buf));
		if (n <= 0)
			break;
		for (off = 0; off + sizeof(*ie) <= (size_t)n;) {
			ie = (struct inotify_event *)(buf + off);
			off += sizeof(*ie) + ie->len;
			ff = mask_to_fflags(ie->mask);
			if (ff == 0)
				continue;
			file = file_by_wd(ie->wd);
			if (file == NULL)
				continue;
			if (*count > 0 && list[*count - 1].file == file) {
				list[*count - 1].fflags |= ff;
				continue;
			}
			if (*count >= max)
				continue;
			list[*count].file = file;
			list[*count].fflags = ff;
			(*count)++;
		}
		if ((size_t)n < sizeof(buf))
			break;
	}
}

static void
drain_sigpipe(void)
{
	char buf[64];

	while (read(sigpipe_fd[0], buf, sizeof(buf)) > 0)
		;
}

/*
 * Wait for activity.  Returns the number of file events collected, -1 if
 * the wait was interrupted (caller should re-check signals).  A key read
 * from the terminal is returned through *key.
 */
static int
wait_events(int timeout_ms, Event *list, int max, int *key)
{
	struct pollfd pfd[3];
	int nfds = 0, iidx, sidx, tidx = -1;
	int r, count = 0;
	char c;

	*key = -1;
	iidx = nfds;
	pfd[nfds].fd = ifd; pfd[nfds].events = POLLIN; nfds++;
	sidx = nfds;
	pfd[nfds].fd = sigpipe_fd[0]; pfd[nfds].events = POLLIN; nfds++;
	if (tty_fd != -1) {
		tidx = nfds;
		pfd[nfds].fd = tty_fd; pfd[nfds].events = POLLIN; nfds++;
	}

	r = poll(pfd, nfds, timeout_ms);
	if (r == -1) {
		if (errno == EINTR)
			return -1;
		err(1, "poll");
	}
	if (r == 0)
		return 0;

	if (pfd[sidx].revents) {
		drain_sigpipe();
		return -1;
	}
	if (tidx != -1 && pfd[tidx].revents) {
		if (read(tty_fd, &c, 1) == 1)
			*key = (unsigned char)c;
	}
	if (pfd[iidx].revents) {
		collect_inotify(list, &count, max);
		/* batch events until things quiet down */
		for (;;) {
			pfd[0].fd = ifd;
			pfd[0].events = POLLIN;
			r = poll(pfd, 1, SETTLE_MS);
			if (r <= 0)
				break;
			collect_inotify(list, &count, max);
		}
	}
	return count;
}

/* discard pending file system events */
static void
consolidate_events(void)
{
	Event tmp[MAX_EVENTS];
	int n = 0;
	struct pollfd pfd;

	pfd.fd = ifd;
	pfd.events = POLLIN;
	while (poll(&pfd, 1, 0) > 0) {
		n = 0;
		collect_inotify(tmp, &n, MAX_EVENTS);
	}
}

/* ------------------------------------------------------------------------ */
/* status filter */

static void
start_status_process(void)
{
	const char *path;
	char default_path[PATH_MAX];
	char *copy;
	struct passwd *pw;
	struct stat sb;
	int fd, fds[2];
	pid_t pid;
	char *argv[8];
	int n = 0;

	path = getenv("ENTR_STATUS_SCRIPT");
	if (path == NULL || *path == '\0') {
		pw = getpwuid(getuid());
		snprintf(default_path, sizeof(default_path), "%s/.entr/status.awk",
		    pw != NULL ? pw->pw_dir : "");
		path = default_path;
	}
	if (stat(path, &sb) == -1) {
		printf("entr: created '%s'\n", path);
		copy = strdup(path);
		if (copy != NULL) {
			(void)mkdir(dirname(copy), 0750);
			free(copy);
		}
		fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0640);
		if (fd == -1)
			err(1, "open");
		if (write(fd, status_template, strlen(status_template)) == -1)
			err(1, "write");
		close(fd);
	}

	if (pipe(fds) == -1)
		err(1, "pipe");
	fflush(stdout);
	pid = fork();
	if (pid == -1)
		err(1, "fork");
	if (pid == 0) {
		dup2(fds[0], STDIN_FILENO);
		close(fds[1]);
		argv[n++] = "awk";
		argv[n++] = "-F";
		argv[n++] = "|";
		argv[n++] = "-f";
		argv[n++] = (char *)path;
		if (status_opt == 1)
			argv[n++] = "-S";
		argv[n] = NULL;
		execvp(argv[0], argv);
		err(1, "exec %s", argv[0]);
	}
	close(fds[0]);
	status_wfd = fds[1];
	status_pid = pid;
}

static void
report_status(int st, const char *utility)
{
	char line[PATH_MAX + 64];
	const char *base;
	char *copy;
	int len;

	if (status_wfd == -1 || status_pid == -1)
		return;
	copy = strdup(utility);
	base = copy != NULL ? basename(copy) : utility;
	if (WIFSIGNALED(st))
		len = snprintf(line, sizeof(line), "signal|%d|%s\n", WTERMSIG(st), base);
	else
		len = snprintf(line, sizeof(line), "exit|%d|%s\n", WEXITSTATUS(st), base);
	if (len > 0)
		(void)write(status_wfd, line, (size_t)len);
	free(copy);
}

/* ------------------------------------------------------------------------ */
/* running the utility */

static void
clear_screen(void)
{
	fflush(stdout);
	if (clear_opt == 1)
		(void)write(STDOUT_FILENO, "\033[2J\033[H", 7);
	else
		(void)write(STDOUT_FILENO, "\033[2J\033[3J\033[H", 11);
}

static void
run_utility(char *argv[])
{
	char **new_argv;
	char *shell;
	int argc, i, replaced = 0;
	pid_t pid;
	int st;

	if (restart_opt)
		stop_child();

	for (argc = 0; argv[argc] != NULL; argc++)
		;
	if (shell_opt) {
		shell = getenv("SHELL");
		if (shell == NULL)
			shell = "/bin/sh";
		new_argv = calloc(5, sizeof(char *));
		if (new_argv == NULL)
			err(1, "calloc");
		new_argv[0] = shell;
		new_argv[1] = "-c";
		new_argv[2] = argv[0];
		new_argv[3] = leading_edge->fn;
		new_argv[4] = NULL;
	} else {
		new_argv = calloc(argc + 1, sizeof(char *));
		if (new_argv == NULL)
			err(1, "calloc");
		for (i = 0; i < argc; i++) {
			if (!replaced && strcmp(argv[i], "/_") == 0) {
				new_argv[i] = leading_edge->fn;
				replaced = 1;
			} else
				new_argv[i] = argv[i];
		}
		new_argv[argc] = NULL;
	}

	if (clear_opt)
		clear_screen();

	if (!restart_opt)
		restore_tty();

	fflush(stdout);
	fflush(stderr);
	pid = fork();
	if (pid == -1)
		err(1, "fork");
	if (pid == 0) {
		if (restart_opt)
			setpgid(0, 0);
		if (tty_fd != -1) {
			dup2(tty_fd, STDIN_FILENO);
			close(tty_fd);
		}
		if (status_wfd != -1) {
			/* keep descriptor numbering compatible: nothing to do */
		}
		setenv("PAGER", "/bin/cat", 0);
		execvp(new_argv[0], new_argv);
		err(1, "exec %s", new_argv[0]);
	}

	if (restart_opt) {
		child_pid = pid;
		free(new_argv);
		return;
	}

	/* wait for the utility; other children may be reaped meanwhile */
	for (;;) {
		pid_t w = waitpid(-1, &st, 0);
		if (w == pid)
			break;
		if (w == -1) {
			if (errno == EINTR)
				continue;
			st = 0;
			break;
		}
		if (w == status_pid) {
			warnx("status process terminated");
			status_pid = -1;
			status_terminated = 1;
		}
	}
	child_status = wait_status_code(st);
	report_status(st, new_argv[0]);
	free(new_argv);

	tty_raw();
	if (!aggressive_opt)
		consolidate_events();
}

/* ------------------------------------------------------------------------ */
/* main loop */

static void
reopen_file(WatchFile *file)
{
	struct stat sb;
	int i, rc = -1;

	if (file->wd != -1) {
		inotify_rm_watch(ifd, file->wd);
		file->wd = -1;
	}
	for (i = 0; i < REOPEN_TRIES; i++) {
		rc = xstat(file->fn, &sb);
		if (rc == 0)
			break;
		msleep(SETTLE_MS);
	}
	if (rc == -1)
		rc = xstat(file->fn, &sb);
	if (rc == -1)
		err(1, "cannot open '%s'", file->fn);
	file->mode = sb.st_mode;
	watch_file(file);
}

static void
watch_loop(char *argv[])
{
	Event ev[MAX_EVENTS];
	int nev, i, n, key;
	int collate_only = 0;
	int do_exec = 0, dir_modified = 0, leading_edge_set = 0;
	int mode_changed;
	WatchFile *file;
	unsigned int ff;
	struct stat sb;

	for (;;) {
		check_signals();
		nev = wait_events(collate_only ? SETTLE_MS : -1, ev, MAX_EVENTS, &key);
		if (nev < 0) {
			nev = 0;
			if (!collate_only)
				continue;
		}
		collate_only = 0;

		if (key == ' ')
			do_exec = 1;
		else if (key == 'q')
			terminate(0);

		/* first pass: directories and files that need to be reopened */
		for (i = 0; i < nev; i++) {
			file = ev[i].file;
			ff = ev[i].fflags;
			if (file->is_dir) {
				if (compare_dir_contents(file)) {
					dir_modified = 1;
					for (n = 0; n < DIR_SETTLE_N; n++) {
						msleep(SETTLE_MS);
						if (!compare_dir_contents(file)) {
							dir_modified = 0;
							break;
						}
					}
				} else
					continue;
				if (ff & (NOTE_DELETE | NOTE_RENAME)) {
					watch_file(file);
					collate_only = 1;
				}
				continue;
			}
			if (ff & (NOTE_DELETE | NOTE_RENAME)) {
				reopen_file(file);
				collate_only = 1;
				do_exec = 1;
			}
		}

		/* second pass: report and decide */
		for (i = 0; i < nev; i++) {
			file = ev[i].file;
			ff = ev[i].fflags;
			mode_changed = 0;
			if (file->is_dir && !dir_modified)
				continue;
			if (ff & NOTE_ATTRIB) {
				if (xstat(file->fn, &sb) == -1)
					continue;
				if (!S_ISREG(sb.st_mode))
					continue;
				if (sb.st_mode != file->mode) {
					file->mode = sb.st_mode;
					mode_changed = 1;
				}
			}
			if (ev_trace)
				fprintf(stderr, "%d/%d: fflags: 0x%x %c %o %s\n", i, nev,
				    ff, file->is_dir ? 'd' : 'r', (unsigned)file->mode,
				    file->fn);
			if (file->is_dir)
				continue;
			if ((ff & (NOTE_WRITE | NOTE_EXTEND | NOTE_DELETE | NOTE_RENAME)) ||
			    mode_changed) {
				do_exec = 1;
				if (!leading_edge_set) {
					leading_edge = file;
					leading_edge_set = 1;
				}
			}
		}

		if (collate_only)
			continue;

		if (do_exec || dir_modified) {
			run_utility(argv);
			do_exec = 0;
			leading_edge_set = 0;
			if (dir_modified) {
				restore_tty();
				errx(2, "directory altered");
			}
			if (oneshot_opt && !restart_opt) {
				restore_tty();
				exit(child_status);
			}
		}
	}
}

/* ------------------------------------------------------------------------ */

int
main(int argc, char *argv[])
{
	int ch, i;

	if (argc > 1 && strcmp(argv[1], "-h") == 0) {
		usage();
		summary();
		return 1;
	}

	while ((ch = getopt(argc, argv, "+acdnprsxz")) != -1) {
		switch (ch) {
		case 'a': aggressive_opt = 1; break;
		case 'c': clear_opt++; break;
		case 'd': dirwatch_opt++; break;
		case 'n': noninteractive_opt = 1; break;
		case 'p': postpone_opt = 1; break;
		case 'r': restart_opt = 1; break;
		case 's': shell_opt = 1; break;
		case 'x': status_opt++; break;
		case 'z': oneshot_opt = 1; break;
		default:
			usage();
			fprintf(stderr, "hint: use -h to display option summary\n");
			return 1;
		}
	}
	argc -= optind;
	argv += optind;

	if (argc == 0 || isatty(STDIN_FILENO)) {
		usage();
		fprintf(stderr, "hint: use -h to display option summary\n");
		return 1;
	}
	if (restart_opt && status_opt)
		errx(1, "-r and -x may not be combined");
	if (shell_opt && argc > 1)
		errx(1, "-s requires commands to be formatted as a single argument");

	parse_restart_signal();

	ev_trace = getenv("EV_TRACE") != NULL;
	follow_symlinks = getenv("ENTR_FOLLOW_SYMLINK") != NULL;
	inotify_workaround = getenv("ENTR_INOTIFY_WORKAROUND") != NULL;

	open_max = read_open_max();
	if (ev_trace)
		fprintf(stderr, "open_max: %d\n", open_max);

	ifd = inotify_init1(IN_CLOEXEC);
	if (ifd == -1)
		err(1, "inotify_init");
	if (inotify_workaround)
		warnx("broken inotify workaround enabled");

	read_file_list(stdin);
	if (nfiles == 0)
		errx(1, "No regular files to watch");

	for (i = 0; i < nfiles; i++) {
		watch_file(files[i]);
		if (files[i]->is_dir)
			files[i]->dir_count = count_dir_entries(files[i]->fn);
	}

	if (!noninteractive_opt) {
		tty_fd = open("/dev/tty", O_RDONLY | O_CLOEXEC);
		if (tty_fd == -1 || tcgetattr(tty_fd, &tty_orig) == -1)
			errx(1, "unable to get terminal attributes, use '-n' to run non-interactively");
		tty_saved = 1;
		atexit(restore_tty);
		tty_raw();
	}

	install_signals();

	if (status_opt)
		start_status_process();

	leading_edge = files[0];
	if (!postpone_opt) {
		run_utility(argv);
		if (oneshot_opt && !restart_opt) {
			restore_tty();
			exit(child_status);
		}
	}

	watch_loop(argv);
	return 0;
}
